<p><strong>Preparer:</strong> <?= e($r['preparer_name']??'—') ?> · <strong>Reviewer:</strong> <?= e($r['reviewer_name']??'—') ?> · <strong>Completed:</strong> <?= e($r['completed_at']??'—') ?></p><p class="finance-muted">Bank CREDIT increases the statement balance and matches a GL debit. Bank DEBIT decreases it and matches a GL credit. Statement lines do not post accounting.</p></section>
<section class="card finance-register"><h2>Bank statement lines</h2><div class="table-responsive"><table class="data-table"><thead><tr><th>#</th><th>Date</th><th>Reference</th><th>Description</th><th>Direction</th><th>Amount</th><th>Cleared</th><th>Unmatched</th></tr></thead><tbody><?php foreach($w['lines']??[] as $l): ?><tr><td><?= (int)$l['line_number'] ?></td><td><?= e($l['transaction_date']) ?></td><td><?= e((string)$l['reference_number']) ?></td><td><?= e($l['description']) ?></td><td><?= e(strtoupper($l['direction'])) ?></td><td><?= e(number_format((float)$l['amount'],2)) ?></td><td><?= e(number_format((float)$l['cleared_amount'],2)) ?></td><td><?= e(number_format((float)$l['amount']-(float)$l['cleared_amount'],2)) ?></td></tr><?php endforeach; ?><?php if(empty($w['lines'])): ?><tr><td colspan="8">No statement lines yet.</td></tr><?php endif; ?></tbody></table></div>
