<section class="card finance-register"><h2>Posted book candidates and carried-forward outstanding items</h2><div class="table-responsive"><table class="data-table"><thead><tr><th>GL line</th><th>Date</th><th>Batch</th><th>Source</th><th>Reference</th><th>Debit / inflow</th><th>Credit / outflow</th><th>Cleared</th><th>Outstanding</th></tr></thead><tbody><?php foreach($w['books']??[] as $b): $amount=max((float)$b['debit_amount'],(float)$b['credit_amount']); ?><tr><td><?= (int)$b['journal_entry_id'] ?></td><td><?= e($b['posting_date']) ?></td><td><?= e($b['batch_number']) ?></td><td><?= e($b['source_type']) ?></td><td><?= e((string)$b['source_number']) ?></td><td><?= e(number_format((float)$b['debit_amount'],2)) ?></td><td><?= e(number_format((float)$b['credit_amount'],2)) ?></td><td><?= e(number_format((float)$b['cleared_amount'],2)) ?></td><td><?= e(number_format(max(0,$amount-(float)$b['cleared_amount']),2)) ?></td></tr><?php endforeach; ?><?php if(empty($w['books'])): ?><tr><td colspan="9">No eligible posted book lines. Shared cash activity is not attributed automatically.</td></tr><?php endif; ?></tbody></table></div>
<?php if($can('prepare')&&($r['status']??'')==='draft'): ?><h3>Match statement to posted book activity</h3><form class="finance-filter-bar" method="post" action="<?= e($url.'/matches') ?>"><input type="hidden" name="_token" value="<?= e($token) ?>"><label>Statement line<select name="statement_line_id" required><?php foreach($w['lines']??[] as $l): if((float)$l['amount']-(float)$l['cleared_amount']<0.001)continue; ?><option value="<?= (int)$l['statement_line_id'] ?>">#<?= (int)$l['line_number'] ?> · <?= e($l['direction']) ?> · <?= e(number_format((float)$l['amount']-(float)$l['cleared_amount'],2)) ?></option><?php endforeach; ?></select></label><label>Posted GL line<select name="journal_entry_id" required><?php foreach($w['books']??[] as $b): $remaining=max((float)$b['debit_amount'],(float)$b['credit_amount'])-(float)$b['cleared_amount'];if($remaining<0.001)continue; ?><option value="<?= (int)$b['journal_entry_id'] ?>"><?= e($b['batch_number']) ?> · line <?= (int)$b['journal_entry_id'] ?> · <?= e(number_format($remaining,2)) ?></option><?php endforeach; ?></select></label><label>Applied amount<input type="number" name="applied_amount" min="0.01" step="0.01" required></label><button class="btn btn-primary" type="submit">Match</button></form><?php endif; ?>
