<section class="card finance-register"><h2>Review and history</h2><?php if($can('prepare')&&($r['status']??'')==='draft'): ?><form method="post" action="<?= e($url.'/submit') ?>"><input type="hidden" name="_token" value="<?= e($token) ?>"><button class="btn btn-primary" type="submit">Send for independent review</button></form><?php endif; ?><?php if($can('review')&&($r['status']??'')==='in_review'): ?><form class="finance-filter-bar" method="post" action="<?= e($url.'/review') ?>"><input type="hidden" name="_token" value="<?= e($token) ?>"><label>Review reason/reference<input name="reason" maxlength="1000"></label><button class="btn btn-primary" name="action" value="complete" type="submit">Complete if balanced</button><button class="btn btn-secondary" name="action" value="reject" type="submit">Return for correction</button></form><?php endif; ?><div class="table-responsive"><table class="data-table"><thead><tr><th>When</th><th>Event</th><th>Actor</th><th>Reason / reference</th></tr></thead><tbody><?php foreach($w['events']??[] as $ev): ?><tr><td><?= e($ev['created_at']) ?></td><td><?= e($ev['event_type']) ?></td><td><?= e($ev['actor_name']) ?></td><td><?= e((string)$ev['reason']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
